import subprocess,re,pathlib
base='dfb1084d7e6aacb1323b5b9f192e65d4eb1cf787'
paths=subprocess.check_output(['git','diff','--name-only',base,'HEAD'],text=True).splitlines()
def strip(s):
 out=[]; i=0; d=0
 while i<len(s):
  if s[i:i+2]=='/-':d+=1;i+=2
  elif d and s[i:i+2]=='-/':d-=1;i+=2
  elif d:i+=1
  elif s[i:i+2]=='--':i=s.find('\\n',i) if '\\n' in s[i:] else len(s)
  else:out.append(s[i]);i+=1
 return ''.join(out)
def decls(txt):
 return {m.group(1):re.sub(r'\\s+',' ',m.group(2)).strip() for m in re.finditer(r'"'^(?:private |protected )?(?:theorem|lemma|def|noncomputable def|abbrev)'"\\s+(\\S+)(.*?)(?::=| where\\b)',strip(txt),re.M|re.S)}
count=0
for p in paths:
 if not p.endswith('.lean') or not p.startswith('MIPStarRE/'):continue
 old=subprocess.run(['git','show',f'{base}:{p}'],capture_output=True,text=True)
 if old.returncode:continue
 a,b=decls(old.stdout),decls(pathlib.Path(p).read_text())
 for n,t in a.items():
  if n in b:
   count+=1
   if t"'!=b[n]:print(p,n,'"'\\n OLD',t,'\\n NEW',b[n])
print('Compared existing signatures:',count)
